def load_count(path):
    try:
        with open(path, encoding="utf-8") as handle:
            return int(handle.read().strip())
    except FileNotFoundError:
        return 0
    except PermissionError as exc:
        raise RuntimeError("count file is not readable") from exc
    except ValueError as exc:
        raise ValueError("count file must contain an integer") from exc

assert load_count("a-file-that-does-not-exist.txt") == 0
